package thaumcraft.test;
import net.minecraftforge.api.distmarker.Dist;
import net.minecraftforge.fml.common.Mod;
import net.minecraftforge.eventbus.api.listener.SubscribeEvent;
import net.minecraftforge.event.TickEvent;
import thaumcraft.*;
import thaumcraft.golems.*;
@Mod.EventBusSubscriber(modid=Thaumcraft.MODID,value=Dist.CLIENT)
public final class FinishClientSync {
 static String state="",panel="",page="";static boolean ready,title;static int frames,syncTicks;
 @SubscribeEvent public static void tick(TickEvent.ClientTickEvent.Post e){if(!FinishClient.mode())return;var mc=net.minecraft.client.Minecraft.getInstance();if(mc.player!=null&&mc.player.isDeadOrDying()&&!FinishClient.tested){mc.player.respawn();return;}if(FinishClient.tested&&mc.gui.screen() instanceof net.minecraft.client.gui.screens.TitleScreen&&!title){title=true;Thaumcraft.LOGGER.info("FINISH_TITLE_READY: world saved and native title active");}if(mc.player==null||mc.level==null)return;
 if(mc.player.containerMenu instanceof SealMenu menu){String next=menu.kind()+":"+menu.value(36)+":"+menu.value(37)+":"+menu.value(15)+":"+menu.value(20);if(!state.equals(next)){state=next;Thaumcraft.LOGGER.info("FINISH_MENU_SYNC {}",state);}if(mc.gui.screen() instanceof thaumcraft.client.GolemScreens.Seal gui){var buttons=gui.children().stream().filter(w->w instanceof net.minecraft.client.gui.components.Button b&&b.visible).map(w->((net.minecraft.client.gui.components.Button)w).getMessage().getString()).toList();String visible=menu.kind()+":"+(buttons.stream().anyMatch(s->s.startsWith("Existing only")||s.startsWith("Replant")||s.startsWith("Keep one")||s.startsWith("Shared"))?"OPTIONS":buttons.stream().anyMatch(s->s.startsWith("Damage"))?"MATCHING":buttons.stream().anyMatch(s->s.startsWith("X"))?"AREA":buttons.stream().anyMatch(s->s.startsWith("Exact"))?"FILTERS":"BASE");if(!page.equals(visible)){page=visible;Thaumcraft.LOGGER.info("FINISH_PANEL {}",page);}if(!panel.equals(state)&&buttons.stream().anyMatch(s->s.startsWith("Existing only")||s.startsWith("Replant"))){panel=state;Thaumcraft.LOGGER.info("FINISH_OPTIONS_PANEL {}",state);}}}
 if(FinishClient.tested&&!ready){int count=0;boolean synchronizedState=true;syncTicks++;for(var entity:mc.level.entitiesForRendering())if(entity instanceof WorkerGolem worker&&FinishClient.gallery.containsKey(worker.getUUID())){var expected=FinishClient.gallery.get(worker.getUUID());boolean matches=worker.material()==expected.material()&&worker.head()==expected.head()&&worker.arms()==expected.arms()&&worker.legs()==expected.legs()&&worker.addon()==expected.addon()&&worker.mode()==2&&!worker.visibleCargo(0).isEmpty();synchronizedState&=matches;ThaumaturgyProbe.check(matches||syncTicks<200,"Native multipart/cargo/mode synchronization timeout: "+worker.getUUID()+" expected="+expected+" mode="+worker.mode()+" cargo="+worker.visibleCargo(0));ThaumaturgyProbe.check(mc.getEntityRenderDispatcher().getRenderer(worker) instanceof thaumcraft.client.GolemRenderer,"Original golem renderer missing");count++;}ThaumaturgyProbe.check(count==6||syncTicks<200,"Native gallery spawn synchronization timeout: "+count);if(count!=6||!synchronizedState)frames=0;if(count==6&&synchronizedState&&++frames>30){ready=true;Thaumcraft.LOGGER.info("FINISH_SCREENSHOT_READY: six synchronized original meshes, all materials, all five heads/arms across gallery and tested native assembled press; physical tasks complete");}}
 }
}
